{"command":"python3 - <<'EOF'
import requests, traceback
url = "https://billing.acme-internal.net/v1/statements/latest"
try:
    r = requests.get(url, timeout=10)
    print("default verify OK:", r.status_code, r.text[:100])
except Exception as e:
    print("default verify FAILED:", type(e).__name__, e)
try:
    r = requests.get(url, verify="/etc/ssl/acme-internal-ca.pem", timeout=10)
    print("CA bundle verify OK:", r.status_code, r.text[:200])
except Exception as e:
    print("CA bundle verify FAILED:", type(e).__name__, e)
EOF"}
